CREATE TABLE IF NOT EXISTS enterprise_incidents(id TEXT PRIMARY KEY NOT NULL,code TEXT NOT NULL UNIQUE,title TEXT NOT NULL,category TEXT NOT NULL,severity TEXT NOT NULL,detected_date TEXT NOT NULL,description TEXT NOT NULL,business_impact TEXT NOT NULL,owner TEXT NOT NULL,commander TEXT NOT NULL,reviewer TEXT NOT NULL,asset_refs TEXT NOT NULL,risk_ref TEXT,bia_ref TEXT,data_classification TEXT NOT NULL,personal_data INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'declared',root_cause TEXT,lessons_learned TEXT,notification_decision TEXT NOT NULL DEFAULT 'pending',notification_rationale TEXT,evidence_reference TEXT,evidence_sha256 TEXT,declared_by TEXT NOT NULL,declared_at TEXT NOT NULL,updated_by TEXT NOT NULL,updated_at TEXT NOT NULL,closed_by TEXT,closed_at TEXT,reopen_count INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS enterprise_incidents_status_severity_idx ON enterprise_incidents(status,severity,detected_date);
CREATE TABLE IF NOT EXISTS enterprise_incident_events(id TEXT PRIMARY KEY NOT NULL,incident_id TEXT NOT NULL,action TEXT NOT NULL,from_status TEXT,to_status TEXT,detail TEXT NOT NULL,evidence_reference TEXT,evidence_sha256 TEXT,actor TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS enterprise_incident_events_incident_date_idx ON enterprise_incident_events(incident_id,created_at);
